<div class="card"><h1>Ended Auctions</h1><?php if(!empty($message)): ?><div class="alert"><?= e($message) ?></div><?php endif; ?><table><tr><th>Title</th><th>Result</th><th>Final Bid</th><th>Winner Contact</th><th>Collection/Delivery Note</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= $r['winner_id'] ? 'Won' : 'Unsold' ?></td><td><?= e($r['current_bid']) ?></td><td><?php if($r['winner_id']): ?><?= e($r['winner_name']) ?><br><?= e($r['winner_email']) ?><br><?= e($r['winner_phone']) ?><?php else: ?>Reserve not met / no winner<?php endif; ?></td><td><?php if($r['winner_id']): ?><?php if(!empty($r['arrangement_note'])): ?><p><?= e($r['arrangement_note']) ?></p><?php endif; ?><form method="post"><input type="hidden" name="listing_id" value="<?= $r['id'] ?>"><input type="hidden" name="buyer_id" value="<?= $r['winner_id'] ?>"><textarea name="arrangement_note" placeholder="Collection or delivery arrangement" required></textarea><button>Save Note</button></form><?php endif; ?></td><td><?php if(!$r['winner_id']): ?><a class="btn" href="index.php?page=relist&id=<?= $r['id'] ?>">Relist</a><?php else: ?><a class="btn secondary" href="index.php?page=seller_reviews">Review Buyer</a><?php endif; ?></td></tr><?php endforeach; ?></table></div>
